"""Publish a provenance-checked, native Godot A/B character-art review."""
from pathlib import Path
import hashlib
import json
import struct

ROOT = Path(__file__).resolve().parents[1]
ARTIFACTS = ROOT / "artifacts"
DIRECTIONS = ["Xuống", "Xuống trái", "Trái", "Lên trái", "Lên", "Lên phải", "Phải", "Xuống phải"]
HTML = r'''<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cổ Sư · Nét vẽ nhân vật 0.47</title><link rel="icon" href="data:,"><style>
:root{color-scheme:dark;--bg:#17211c;--panel:#303a34;--line:#495449;--text:#ede5d2;--muted:#b5bcaf;--gold:#d6b77e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,sans-serif}main{max-width:1024px;margin:auto;padding:40px 32px 64px}.eyebrow{font-size:12px;letter-spacing:.14em;color:var(--gold);text-transform:uppercase}h1{font-family:Georgia,serif;font-size:clamp(30px,5vw,49px);font-weight:400;line-height:1.1;margin:13px 0 20px}header p{max-width:720px;color:var(--muted);margin:0}button,select,input{font:inherit}button,select{border:1px solid var(--line);border-radius:4px;padding:8px 12px;background:#25332a;color:var(--text)}button{cursor:pointer}button:hover,button:focus-visible,select:focus-visible{border-color:var(--gold)}button:disabled{opacity:.4;cursor:wait}button[aria-pressed=true]{color:#17211c;background:var(--gold);border-color:var(--gold)}nav{display:flex;gap:7px;flex-wrap:wrap;margin:28px 0 20px;padding-block:18px;border-block:1px solid var(--line)}nav button{background:transparent;font-size:14px}label{display:flex;flex-direction:column;gap:5px;color:var(--muted);font-size:12px}.controls{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:20px}select{min-width:125px}#pose{min-width:205px}.compare-controls{display:flex;gap:7px}.heading{display:flex;justify-content:space-between;gap:12px;align-items:baseline;flex-wrap:wrap;margin:21px 0 9px}.heading h2{font-size:18px;font-weight:500;margin:0}.heading span{font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}.stage{background:var(--panel);outline:1px solid var(--line);border-radius:5px;overflow:hidden;margin:0}canvas{display:block;height:auto;max-width:100%;margin:auto}.caption{font-size:12px;color:var(--muted);padding:12px 16px;border-top:1px solid var(--line);margin:0;background:#243029}.playback{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:15px 0}.playback input{flex:1;min-width:110px;accent-color:var(--gold)}.playback output{width:60px;font-size:13px;color:var(--muted);font-variant-numeric:tabular-nums}.notes{display:grid;grid-template-columns:1fr 1fr;gap:25px;margin-top:25px}.notes h3{font-size:14px;font-weight:500;margin:0 0 6px}.notes p{font-size:13px;margin:0;color:var(--muted)}a{color:var(--gold);text-underline-offset:3px}footer{display:flex;flex-wrap:wrap;gap:12px 20px;border-top:1px solid var(--line);padding-top:16px;margin-top:28px;font-size:12px;color:var(--muted)}.error{padding:12px;border-left:3px solid #d5a784;color:#e4bfa2;margin-bottom:15px}[hidden]{display:none!important}@media(max-width:600px){main{padding:25px 16px 40px}nav{gap:6px;margin-top:22px;padding-block:13px}nav button{font-size:12px;padding:7px 9px}.controls{gap:10px}#pose{min-width:185px}.notes{grid-template-columns:1fr;gap:17px}.compare-controls button{padding:7px 10px;font-size:12px}h1{max-width:320px}.stage{margin-inline:-6px}.caption{font-size:11px;padding:10px}}
</style></head><body><main><header><div class="eyebrow">Cổ Sư · Character art · 0.47</div><h1>Nét vẽ nhân vật</h1><p>Đặt bản 0.46 và bản 0.47 cạnh nhau ở cùng hướng, cùng tư thế, cùng kích thước. Kiểm đường viền và cách tô từng mảng, rồi phát chuyển động để thấy các chi tiết khi gập khớp.</p></header><nav id="directions" aria-label="Hướng nhân vật"></nav><p id="error" class="error" role="alert" hidden></p>
<div class="controls"><label>Nhân vật<select id="body"><option value="male">Nam</option><option value="female">Nữ</option></select></label><label>Kiểm tra<select id="mode"><option value="poses">Tư thế</option><option value="motion">Chuyển động</option></select></label><label id="poseField">Thời điểm<select id="pose"></select></label><label id="actionField" hidden>Động tác<select id="action"><option value="attack">Tấn công</option><option value="defend">Phòng thủ</option><option value="gather">Hái lượm</option><option value="mine">Khai khoáng</option><option value="walk">Đi bộ</option><option value="run">Chạy</option></select></label><label id="speedField" hidden>Tốc độ<select id="speed"><option value="1">1×</option><option value=".5">½×</option><option value=".25">¼×</option></select></label></div>
<div class="compare-controls" aria-label="Cách so sánh"><button data-compare="both" aria-pressed="true">Cạnh nhau</button><button data-compare="before" aria-pressed="false">Bản trước</button><button data-compare="after" aria-pressed="false">Bản mới</button></div><div class="heading"><h2 id="heading"></h2><span id="status" role="status"></span></div>
<figure class="stage"><canvas id="surface" width="960" height="380" aria-label="Ảnh native Godot đối chiếu nhân vật 0.46 với 0.47"></canvas><figcaption class="caption">Hai cỡ vẽ: cận cảnh 200 px và cỡ cấu hình trong game 48 px. Chọn “Bản mới” để xem riêng trên màn hình nhỏ.</figcaption></figure><img id="native" hidden alt="Khung hình Godot gốc"><div class="playback" id="playback" hidden><button id="prev" aria-label="Frame trước">←</button><button id="play" disabled>Phát</button><button id="next" aria-label="Frame sau">→</button><input id="slider" type="range" min="0" max="23" value="0" aria-label="Chọn frame"><output id="count"></output></div>
<div class="notes"><section><h3>Đối chiếu công bằng</h3><p>Giữ nguyên concept đầu và thân, khung xương, điểm bám và pha động tác. Bản trước dùng shader và atlas đã đóng băng; bản mới dùng nguồn hiện tại. Mỗi cặp được kiểm cùng một pose.</p></section><section><h3>Chuyển động từ Godot</h3><p>Mỗi clip gồm 24 khung hình native, có chuyển trạng thái và chuyển động phụ của nhân vật trong game. Trang phát các ảnh thật, không nội suy ảnh hay thêm chuyển động bằng CSS.</p></section></div><footer><a id="png" href="">PNG gốc</a><a id="report" href="">Dữ liệu native</a><a href="concept47_review.json">Dấu vết nguồn</a><a id="world" href="concept47_world_front.png">Xem trong game</a><a href="concept46_character_workshop.html">Xưởng xương 0.46</a><span id="coverage"></span></footer></main><script>
const data=__DATA__,names=__NAMES__,$=id=>document.getElementById(id),poseLabels=['Đứng','Kiếm · lấy đà','Kiếm · ra đòn','Kiếm · thu tay','Phòng thủ','Hái lượm · tiếp xúc','Khai khoáng · tiếp xúc','Đi bộ','Chạy'];
let direction=0,frame=0,compare='both',playing=false,epoch=0,startFrame=0,raf=0,loadGeneration=0,drawGeneration=0;const cache=new Map();
function r(){return data.directions[direction]}function clip(){return r().clips[$('action').value]}function stop(){playing=false;cancelAnimationFrame(raf);$('play').textContent='Phát'}function failure(error){stop();$('error').hidden=false;$('error').textContent=error.message||String(error);console.error(error)}
function source(){if($('mode').value==='poses')return `${r().folder}/${$('body').value}/pose${String($('pose').value).padStart(2,'0')}.png`;return `${clip().folder.replace('{body}',$('body').value)}/frame${String(frame).padStart(3,'0')}.png`}
function draw(image){const width=compare==='both'?960:480,canvas=$('surface');if(canvas.width!==width)canvas.width=width;canvas.style.width=width+'px';const ctx=canvas.getContext('2d');ctx.clearRect(0,0,width,380);ctx.drawImage(image,compare==='after'?480:0,0,width,380,0,0,width,380);canvas.dataset.source=image.getAttribute('src');canvas.dataset.compare=compare;canvas.dataset.ready='true'}
function update(){const motion=$('mode').value==='motion',file=source();for(const button of $('directions').children)button.setAttribute('aria-pressed',String(+button.dataset.direction===direction));for(const button of document.querySelectorAll('[data-compare]'))button.setAttribute('aria-pressed',String(button.dataset.compare===compare));$('poseField').hidden=motion;$('actionField').hidden=!motion;$('speedField').hidden=!motion;$('playback').hidden=!motion;$('heading').textContent=`${$('body').selectedOptions[0].text} · Hướng ${names[direction].toLowerCase()}`;$('status').textContent=motion?`${$('action').selectedOptions[0].text} · ${((frame+.75)*clip().duration/clip().frames).toFixed(3)} s`:poseLabels[+$('pose').value];$('slider').value=frame;$('count').textContent=`${frame+1} / 24`;$('png').href=file;$('report').href=r().report;$('surface').dataset.ready='false';const generation=++drawGeneration, image=$('native');image.onload=()=>{if(generation===drawGeneration)draw(image)};image.onerror=()=>failure(new Error('Không tải được '+file));if(image.getAttribute('src')!==file)image.src=file;else if(image.complete&&image.naturalWidth===960)draw(image)}
async function prepare(){if($('mode').value!=='motion')return;const c=clip(),folder=c.folder.replace('{body}',$('body').value),generation=++loadGeneration;$('play').disabled=true;if(!cache.has(folder)){const images=await Promise.all(Array.from({length:c.frames},(_,n)=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Không tải được '+image.src));image.src=`${folder}/frame${String(n).padStart(3,'0')}.png`})));cache.set(folder,images);while(cache.size>2)cache.delete(cache.keys().next().value)}if(generation===loadGeneration)$('play').disabled=false}
function refresh(){stop();frame=0;update();prepare().catch(failure)}function step(amount){stop();frame=(frame+amount+24)%24;update()}function tick(now){if(!playing)return;frame=(startFrame+Math.floor((now-epoch)*+$('speed').value/1000/clip().duration*24))%24;update();raf=requestAnimationFrame(tick)}
names.forEach((name,index)=>{const button=document.createElement('button');button.dataset.direction=index;button.textContent=name;button.onclick=()=>{direction=index;refresh()};$('directions').append(button)});poseLabels.forEach((name,index)=>$('pose').add(new Option(name,String(index))));for(const id of ['body','mode','pose','action'])$(id).onchange=refresh;for(const button of document.querySelectorAll('[data-compare]'))button.onclick=()=>{compare=button.dataset.compare;update()};$('play').onclick=()=>{if(playing){stop();return}playing=true;startFrame=frame;epoch=performance.now();$('play').textContent='Dừng';raf=requestAnimationFrame(tick)};$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('slider').oninput=()=>{stop();frame=+$('slider').value;update()};$('speed').onchange=()=>{startFrame=frame;epoch=performance.now()};document.addEventListener('keydown',event=>{if($('mode').value!=='motion'||['SELECT','INPUT'].includes(event.target.tagName))return;if(event.key==='ArrowLeft'){event.preventDefault();step(-1)}if(event.key==='ArrowRight'){event.preventDefault();step(1)}if(event.code==='Space'&&!$('play').disabled){event.preventDefault();$('play').click()}});$('coverage').textContent=`${data.total_native_frames.toLocaleString('vi')} khung native · 8 hướng · 2 giới tính`;update();
</script></body></html>'''


def build():
    directions = {}
    common_sources = None
    capture_count = native_frames = equal_checks = 0
    for direction in range(8):
        path = ARTIFACTS / f"concept47_d{direction}_native.json"
        report = json.loads(path.read_text())
        if report["poses_only"]:
            raise ValueError(f"Direction {direction} has no motion evidence")
        sources = report["source_sha256"]
        if not sources or any(hashlib.sha256((ROOT / name).read_bytes()).hexdigest() != sha for name, sha in sources.items()):
            raise ValueError(f"Stale native captures for direction {direction}; recapture after source freeze")
        if common_sources is None:
            common_sources = sources
        if common_sources != sources:
            raise ValueError("Directions were captured from different source versions")
        assert report["baseline_geometry_identical"] and report["baseline_material_preserved"]
        assert len(report["captures"]) == 306 and report["native_frames"] == 153
        for capture in report["captures"]:
            with (ARTIFACTS / capture).open("rb") as image:
                header = image.read(24)
            assert header[:8] == b"\x89PNG\r\n\x1a\n"
            assert struct.unpack(">II", header[16:24]) == (960, 380), capture
        directions[str(direction)] = {key: report[key] for key in ["direction", "label", "folder", "poses", "clips", "bodies"]}
        directions[str(direction)]["report"] = path.name
        directions[str(direction)]["source_current"] = True
        capture_count += len(report["captures"])
        native_frames += report["native_frames"]
        equal_checks += report["identical_pose_checks"]
    output = {"revision": 47, "directions": directions, "total_native_frames": native_frames, "total_body_pngs": capture_count, "identical_pose_checks": equal_checks, "source_sha256": common_sources, "source_current": True, "native_crop_size": [960, 380], "baseline": "0.46 atlas and shader, identical current rig and poses"}
    (ARTIFACTS / "concept47_review.json").write_text(json.dumps(output, ensure_ascii=False, indent=2))
    html = HTML.replace("__DATA__", json.dumps(output, ensure_ascii=False)).replace("__NAMES__", json.dumps(DIRECTIONS, ensure_ascii=False))
    (ARTIFACTS / "concept47_character_review.html").write_text(html)
    print(json.dumps({"native_frames": native_frames, "body_pngs": capture_count, "identical_pose_checks": equal_checks, "source_current": True}))


if __name__ == "__main__":
    build()
